// Arma el aviso de venta con todo lo que hace falta para despachar.
const o = $input.first().json.body || $input.first().json || {};

const fmt = n => '$' + Number(n || 0).toLocaleString('es-AR', {minimumFractionDigits: 2});
const cli = o.customer || {};
const env = o.shipping_address || {};
const nombre = [cli.first_name, cli.last_name].filter(Boolean).join(' ')
             || [env.first_name, env.last_name].filter(Boolean).join(' ')
             || 'sin nombre';

const items = (o.line_items || [])
  .map(li => `  ${li.quantity}x ${li.title} - ${fmt(li.price)}`).join('\n');

const lineas = [
  'VENTA EN GONVRA',
  '',
  `Pedido #${o.order_number || o.name || '?'}  -  ${fmt(o.total_price)}`,
  `Pago: ${o.financial_status || '?'}`,
  '',
  'CLIENTE',
  `  ${nombre}`,
  `  ${o.email || 'sin mail'}`,
  `  ${o.phone || env.phone || 'sin telefono'}`,
  '',
  'ENVIAR A',
  `  ${env.address1 || ''} ${env.address2 || ''}`.trim(),
  `  ${env.city || ''}, ${env.province || ''} (${env.zip || ''})`,
  '',
  'COMPRO',
  items || '  (sin detalle)',
  '',
  'Entra a Shopify y despachalo.'
];

return [{ json: { texto: lineas.join('\n') } }];
